-- #205 item 2: integrate the updated species reference table
-- (field corrections + animal-type assignment + 3 new reference rows).
-- Safe on empty databases (replay): every INSERT is guarded and
-- animal-type resolution falls back to NULL when the type is absent.

-- 1) creaves_species typo fix (base column + fr mirror)
UPDATE species SET creaves_species = 'Grimpereau des jardins' WHERE ID = 'SP104';
UPDATE translations SET value = 'Grimpereau des jardins' WHERE table_name = 'species' AND record_id = 'SP104' AND field = 'creaves_species' AND locale = 'fr';

