-- 3) new reference rows (Furet is a second entry sharing Mustela putorius
-- with the wild Putois SP283, so createSpecies' name-based seed skips it).
INSERT INTO species (ID, species, class, family, creaves_species, subside_group, created_at, updated_at, `order`, game, agw_group, native_status, huntable, animaltype_id) SELECT 'SP498', 'Mustela putorius', 'Mammalia', 'Mustélidés', 'Furet', 'SG4', '2026-09-26 18:18:33', '2026-09-26 18:18:33', 'Carnivora', 0, 'Domestique', 'NS4', 0, (SELECT id FROM animaltypes WHERE id = 'e02fc64b-7319-4c57-be03-6be34a12db28') FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM species WHERE ID = 'SP498');
INSERT INTO species (ID, species, class, family, creaves_species, subside_group, created_at, updated_at, `order`, game, agw_group, native_status, huntable, animaltype_id) SELECT 'SP499', 'Iguana iguana', 'Reptilia', 'Iguanidae', 'Iguane Vert', 'SG4', '2026-09-26 18:18:33', '2026-09-26 18:18:33', 'Squamata', 0, 'Reptile', 'NS2', 0, (SELECT id FROM animaltypes WHERE id = 'b3e9ca56-b28e-407a-8b6d-5f39970d2a17') FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM species WHERE ID = 'SP499');
