-- 4) fr translation mirrors for the new rows (canonical = base values)
INSERT INTO translations (id, table_name, record_id, field, locale, value, created_at, updated_at) SELECT UUID(), 'species', 'SP498', t.fld, 'fr', t.val, NOW(), NOW() FROM (SELECT 'species' AS fld, 'Mustela putorius' AS val UNION ALL SELECT 'class', 'Mammalia' UNION ALL SELECT 'family', 'Mustélidés' UNION ALL SELECT 'creaves_species', 'Furet' UNION ALL SELECT 'subside_group', 'SG4' UNION ALL SELECT 'order', 'Carnivora' UNION ALL SELECT 'agw_group', 'Domestique' UNION ALL SELECT 'native_status', 'NS4') t WHERE EXISTS (SELECT 1 FROM species WHERE ID = 'SP498') AND NOT EXISTS (SELECT 1 FROM translations x WHERE x.table_name = 'species' AND x.record_id = 'SP498' AND x.field = t.fld AND x.locale = 'fr');
